//! Unicode character properties, looked up per code point. Tier 0.
//!
//! The tables come from the Unicode Character Database 16.0.0 files in `data/`. `gen.zig` turns
//! them into the generated module `unicode_tables` at build time (build.zig). Parsing the files
//! at comptime was measured first: LineBreak.txt alone (254 KB) took 92 s on 0.17.1, and the
//! algorithms need about 1.4 MB of them, so the tables are generated by a host step instead.
//!
//! Enum tags are the UCD value names exactly (`.CR`, `.Regional_Indicator`, `.AL`), so the
//! conformance files and the tables share one vocabulary. Each algorithm reads one packed row
//! per code point: everything grapheme, word or line breaking needs is in that row.

const std = @import("std");
const tables = @import("unicode_tables");

/// Grapheme_Cluster_Break (UAX #29, table 2).
pub const Gcb = enum(u4) { Other, CR, LF, Control, Extend, ZWJ, Regional_Indicator, Prepend, SpacingMark, L, V, T, LV, LVT };
/// Indic_Conjunct_Break, for rule GB9c.
pub const InCB = enum(u2) { None, Linker, Consonant, Extend };
/// Word_Break (UAX #29, table 3).
pub const Wb = enum(u5) { Other, CR, LF, Newline, Extend, ZWJ, Regional_Indicator, Format, Katakana, Hebrew_Letter, ALetter, Single_Quote, Double_Quote, MidNumLet, MidLetter, MidNum, Numeric, ExtendNumLet, WSegSpace };
/// Line_Break (UAX #14, table 1), before rule LB1 resolves AI, SA, SG, XX and CJ.
pub const Lb = enum(u6) { BK, CR, LF, CM, NL, SG, WJ, ZW, GL, SP, ZWJ, B2, BA, BB, HY, CB, CL, CP, EX, IN, NS, OP, QU, IS, NU, PO, PR, SY, AI, AK, AL, AP, AS, CJ, EB, EM, H2, H3, HL, ID, JL, JV, JT, RI, SA, VF, VI, XX };
/// Bidi_Class (UAX #9, table 4).
pub const BidiClass = enum(u5) { L, R, AL, EN, ES, ET, AN, CS, NSM, BN, B, S, WS, ON, LRE, LRO, RLE, RLO, PDF, LRI, RLI, FSI, PDI };
/// Script (Scripts.txt). Tags are the long value names; `Unknown` is 0.
pub const Script = tables.Script;

/// What grapheme cluster breaking reads for one code point.
pub const Grapheme = bitpack struct(u8) { gcb: Gcb, incb: InCB, ext_pict: bool, _pad: u1 = 0 };
/// What word breaking reads for one code point.
pub const Word = bitpack struct(u8) { wb: Wb, ext_pict: bool, _pad: u2 = 0 };
/// What line breaking reads for one code point: the class and the other properties its rules name.
pub const Line = bitpack struct(u16) {
    lb: Lb,
    /// East_Asian_Width is F, W or H (`$EastAsian` in UAX #14).
    east_asian: bool,
    /// Extended_Pictographic and General_Category Cn (rule LB30b).
    pict_cn: bool,
    /// General_Category Pi (LB15a, LB19).
    pi: bool,
    /// General_Category Pf (LB15b, LB19).
    pf: bool,
    /// General_Category Mn or Mc (LB1 resolves SA to CM for these).
    mark: bool,
    _pad: u5 = 0,
};
/// Bidi_Paired_Bracket and Bidi_Paired_Bracket_Type (BidiBrackets.txt).
pub const Bracket = struct { pair: u21, kind: enum(u2) { none, open, close } };

pub fn grapheme(cp: u21) Grapheme {
    return @bitCast(stage("grapheme", cp));
}
pub fn word(cp: u21) Word {
    return @bitCast(stage("word", cp));
}
pub fn line(cp: u21) Line {
    return @bitCast(stage("line", cp));
}
pub fn bidiClass(cp: u21) BidiClass {
    return @fromBackingInt(@intCast(stage("bidi", cp)));
}
pub fn script(cp: u21) Script {
    return @fromBackingInt(@intCast(stage("script", cp)));
}
pub fn bracket(cp: u21) Bracket {
    const i = find(&tables.bracket_cp, cp);
    const hit = tables.bracket_cp[i] == cp;
    return .{ .pair = if (hit) tables.bracket_pair[i] else cp, .kind = if (hit) (if (tables.bracket_open[i]) .open else .close) else .none };
}

/// Three-stage lookup: middle block, leaf block, value. Three dependent loads, no branch.
inline fn stage(comptime name: []const u8, cp: u21) @TypeOf(@field(tables, name ++ "_stage3")[0]) {
    const mid = @field(tables, name ++ "_mid");
    const leaf = @field(tables, name ++ "_leaf");
    const c: usize = cp;
    const m: usize = @field(tables, name ++ "_stage1")[c >> (mid + leaf)];
    const l: usize = @field(tables, name ++ "_stage2")[(m << mid) | ((c >> leaf) & ((1 << mid) - 1))];
    return @field(tables, name ++ "_stage3")[(l << leaf) | (c & ((1 << leaf) - 1))];
}

/// Index of the last entry of `starts` that is <= cp (0 when cp is below them all). Fixed trip
/// count for a given table: the halving loop selects instead of branching on the comparison.
fn find(starts: []const u21, cp: u21) usize {
    var lo: usize = 0;
    var len = starts.len;
    while (len > 1) {
        const half = len / 2;
        lo = if (starts[lo + half] <= cp) lo + half else lo;
        len -= half;
    }
    return lo;
}

test "table size" {
    // 79,320 bytes of three-stage tables plus the bracket list (two-stage was 228,480,
    // run-length 57,272).
    var bytes: usize = @sizeOf(@TypeOf(tables.bracket_cp)) + @sizeOf(@TypeOf(tables.bracket_pair)) + @sizeOf(@TypeOf(tables.bracket_open));
    inline for (.{ "grapheme", "word", "line", "bidi", "script" }) |name| {
        bytes += @sizeOf(@TypeOf(@field(tables, name ++ "_stage1"))) + @sizeOf(@TypeOf(@field(tables, name ++ "_stage2"))) +
            @sizeOf(@TypeOf(@field(tables, name ++ "_stage3")));
    }
    try std.testing.expect(bytes < 90_000);
}

test "property lookups match the data files" {
    try std.testing.expectEqual(Gcb.CR, grapheme('\r').gcb);
    try std.testing.expectEqual(Gcb.LVT, grapheme(0xAC01).gcb);
    try std.testing.expectEqual(InCB.Consonant, grapheme(0x0915).incb);
    try std.testing.expect(grapheme(0x1F600).ext_pict);
    try std.testing.expectEqual(Wb.ALetter, word('a').wb);
    try std.testing.expectEqual(Lb.AL, line('a').lb);
    try std.testing.expectEqual(Lb.ID, line(0x4E00).lb);
    try std.testing.expect(line(0x4E00).east_asian);
    try std.testing.expect(line(0x00AB).pi);
    try std.testing.expectEqual(Lb.XX, line(0x10FFFF).lb);
    try std.testing.expectEqual(BidiClass.R, bidiClass(0x05D0));
    try std.testing.expectEqual(BidiClass.AL, bidiClass(0x0627));
    try std.testing.expectEqual(BidiClass.R, bidiClass(0x05FF)); // unassigned: @missing default
    try std.testing.expectEqual(Script.Latin, script('a'));
    try std.testing.expectEqual(Script.Unknown, script(0x10FFFF));
    try std.testing.expectEqual(Bracket{ .pair = ')', .kind = .open }, bracket('('));
    try std.testing.expectEqual(Bracket{ .pair = 'a', .kind = .none }, bracket('a'));
}
